scores = [{"name": "Piko", "score": 300}, {"name": "Emma", "score": 450}]

def handle(method, path, body=None):
    if path != "/scores":
        return 404, {"error": "no such path"}
    if method == "GET":
        return 200, sorted(scores, key=lambda s: s["score"], reverse=True)
    if method == "POST":
        if not body or "name" not in body or "score" not in body:
            return 400, {"error": "missing information"}
        entry = {"name": body["name"], "score": body["score"]}
        scores.append(entry)
        return 201, entry
    return 404, {"error": "no such path"}

print(handle("GET", "/scores"))
print(handle("POST", "/scores", {"name": "Ben", "score": 120}))
